cd /workspace && PYTHONPATH=/workspace/project:/opt/emicro-deps timeout 300 python3 - <<'EOF'
import sys, itertools; sys.path[:0]=['/workspace/project','/opt/emicro-deps']
import syntax
from compiler import automata, compiler
tests=[('match(A) or not(match(A))','(match(A) or not(match(A))) allow;'),
       ('only-drop','not(match()) allow;'),
       ('and-not','(match(A) and not(match(A))) allow;'),
       ('not-startswith-empty','not(startswith()) allow;'),
       ('startswith-drop-contains','startswith(A) allow; contains(A) drop;'),
       ('endswith-not-startswith','endswith(A,B) allow; not(startswith(A)) drop;'),
       ('deep nesting','(' * 15 + 'match(A)' + ')' * 15 + ' allow;'),
       ('not chain','not(not(not(not(not(match(A)))))) allow;'),
       ('mixed','(contains(A,B) or endswith(B,A)) allow; (startswith(A) and match(B)) drop;')]
names=['A','B']; idx={'A':0,'B':1}
for label,text in tests:
    rules,a,s=syntax.parse(text)
    try: fast=automata.compile_rules(rules,[1,2],idx)
    except Exception as e: fast='%s: %s'%(type(e).__name__,e)
    try: ref=compiler.compile_rules(rules,[1,2],idx)
    except Exception as e: ref='%s: %s'%(type(e).__name__,e)
    # brute force truth table
    def ev(p, w):
        k=p[0]
        if k=='not': return not ev(p[1],w)
        if k=='and': return ev(p[1],w) and ev(p[2],w)
        if k=='or': return ev(p[1],w) or ev(p[2],w)
        path=[idx[n] for n in p[1]]
        if k=='match': return list(w)==path
        if k=='startswith': return list(w)[:len(path)]==path
        if k=='endswith': return not path or list(w)[-len(path):]==path
        if k=='contains':
            if not path: return True
            return any(list(w)[i:i+len(path)]==path for i in range(len(w)-len(path)+1))
    def allowed(w, rules=rules):
        al=dr=False
        for p,act in rules:
            if ev(p,list(w)):
                if act: al=True
                else: dr=True
        return al and not dr
    def run(img,w):
        if type(img) is not dict: return None
        st=0
        for sym in w:
            if st==4294967295: return False
            st=img['rows'][st][sym]
        return st!=4294967295 and img['accept'][st]
    bad=[]
    for L in range(0,9):
        for w in itertools.product(range(2),repeat=L):
            want=allowed(w); got=run(fast,w)
            if got is not None and got!=want: bad.append(w)
    print('%-24s agree=%s bad=%d %s' % (label, fast==ref, len(bad),
          (fast['rows_count'] if type(fast) is dict else fast)))
    if bad: print('   ',bad[:5])
EOF
